DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.telegram_confirm_action(uuid,text,text,boolean)'::regprocedure) INTO d; IF position('INSERT INTO public.telegram_deliveries(dedupe_key,chat_id,message) VALUES(''announcement:''||a.id::text,c.support_chat_id,a.message) ON CONFLICT DO NOTHING;' IN d)=0 THEN RAISE EXCEPTION 'ANNOUNCEMENT_FUNCTION_CHANGED'; END IF; d:=replace(d,'INSERT INTO public.telegram_deliveries(dedupe_key,chat_id,message) VALUES(''announcement:''||a.id::text,c.support_chat_id,a.message) ON CONFLICT DO NOTHING;','INSERT INTO public.telegram_deliveries(dedupe_key,chat_id,message,website_user_id) SELECT ''broadcast:''||a.id::text||'':''||l.telegram_user_id,l.telegram_user_id,a.message,l.website_user_id FROM public.telegram_account_links l WHERE l.notify_announcements=true ON CONFLICT DO NOTHING;'); d:=replace(d,'''group'',''support''','''recipients'',''opted_in_linked_users'''); EXECUTE d; END; $$;
CREATE OR REPLACE FUNCTION public.telegram_offer_immutable() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.name IS DISTINCT FROM OLD.name OR NEW.amount_paise IS DISTINCT FROM OLD.amount_paise OR NEW.credits IS DISTINCT FROM OLD.credits OR NEW.days IS DISTINCT FROM OLD.days OR NEW.tier IS DISTINCT FROM OLD.tier OR NEW.reason IS DISTINCT FROM OLD.reason OR NEW.expires_at IS DISTINCT FROM OLD.expires_at THEN RAISE EXCEPTION 'OFFER_IMMUTABLE'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER telegram_offer_immutable BEFORE UPDATE ON public.telegram_offers FOR EACH ROW EXECUTE FUNCTION public.telegram_offer_immutable();
REVOKE ALL ON FUNCTION public.telegram_confirm_action(uuid,text,text,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.telegram_confirm_action(uuid,text,text,boolean) TO service_role;